import{_ as a,H as t,f as s,i as r}from"./chunks/framework.CSxcEb-0.js";const p=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md"}'),n={name:"guide/settings.md"};function i(o,e,l,d,h,g){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Open <strong>Settings</strong> from the sidebar. On desktop, section links also appear in the top toolbar when you are on Settings.</p><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h2><p><strong>Settings → Theme</strong> (or Appearance):</p><ul><li><strong>Dark / Light</strong> — neutral UI</li><li><strong>TemPad Dark</strong> — phosphor green and amber on black (TVA terminal)</li><li><strong>TemPad Light</strong> — parchment and forest ink (TVA dossier)</li></ul><p>Optional: scheduled light/dark switching by time of day.</p><h2 id="lists" tabindex="-1">Lists <a class="header-anchor" href="#lists" aria-label="Permalink to &quot;Lists&quot;">​</a></h2><ul><li><strong>Default list</strong> for new tasks</li><li><strong>List colors</strong> — presets, custom hex, <strong>Random color</strong></li><li><strong>Keep list colors across themes</strong> — same hex everywhere, or slight light/dark adjustment at render time</li></ul><p>Colors appear on calendar chips, task rows, filters, and list indicators.</p><h2 id="scheduling-hours" tabindex="-1">Scheduling hours <a class="header-anchor" href="#scheduling-hours" aria-label="Permalink to &quot;Scheduling hours&quot;">​</a></h2><p>Profiles define when tasks <em>can</em> be placed (e.g. Work hours 9–5 weekdays, Personal evenings). Each <strong>list</strong> links to one profile.</p><p>Expand <strong>Manage scheduling hours</strong> to edit day-by-day enable/start/end. Copy first day to all days when setting up a new profile.</p><h2 id="scheduler" tabindex="-1">Scheduler <a class="header-anchor" href="#scheduler" aria-label="Permalink to &quot;Scheduler&quot;">​</a></h2><ul><li><strong>Scheduling horizon</strong> — how many weeks ahead to plan (default 8)</li><li><strong>Schedule breaks</strong> — optional gaps after X minutes of work and/or X tasks (empty space in the plan, not separate “Break” events)</li><li><strong>Reschedule delay</strong>, splittable defaults, buffer before/after events, dependency drag direction, and related toggles</li></ul><h2 id="calendar-display" tabindex="-1">Calendar display <a class="header-anchor" href="#calendar-display" aria-label="Permalink to &quot;Calendar display&quot;">​</a></h2><p>Week/day/month default, show event end times, skipped tasks on calendar, inbox in Eisenhower matrix, etc.</p><h2 id="google-calendar" tabindex="-1">Google Calendar <a class="header-anchor" href="#google-calendar" aria-label="Permalink to &quot;Google Calendar&quot;">​</a></h2><p>See the dedicated <a href="./google-calendar.html">Google Calendar</a> page.</p><h2 id="getting-started-checklist" tabindex="-1">Getting started checklist <a class="header-anchor" href="#getting-started-checklist" aria-label="Permalink to &quot;Getting started checklist&quot;">​</a></h2><p>At the top of Settings, new users see a dismissible checklist linking to the <a href="./../getting-started.html">getting started tutorial</a>. Dismiss hides it permanently (synced when signed in).</p>',20)])])}const u=a(n,[["render",i]]);export{p as __pageData,u as default};
